import clsx from 'clsx';
import React from 'react';
import { useTranslation } from '@/hooks/useTranslation';

/**
 * 全局加载动画 —— 视觉复刻 Uiverse by csemszepp / ugly-crab-22（MIT License）。
 * 源码 https://uiverse.io/csemszepp/ugly-crab-22
 * 原组件是 400px 舞台 + 双球 osc-l/osc-r 振荡，靠 filter: blur+contrast
 * 让两球在中点融合（gooey 效果）；这里等比缩小到 130px 舞台，
 * 舞台改圆形（orb），并按主题反色：浅色底深球、暗色底浅球。
 *
 * 位置：由原版的「贴顶 (top-4 + 安全区padding)」改为屏幕垂直居中
 * （top-1/2 -translate-y-1/2），各使用处的 flex 居中容器不变。
 */
const Spinner: React.FC<{
  loading: boolean;
  className?: string;
}> = ({ loading, className }) => {
  const _ = useTranslation();
  if (!loading) return null;

  return (
    <div
      className={clsx(
        'absolute left-1/2 top-1/2 flex -translate-x-1/2 -translate-y-1/2 transform items-center justify-center',
        className,
      )}
      role='status'
    >
      <div className='spinner-goo-stage'>
        <span className='spinner-goo-blob spinner-goo-blob--l' />
        <span className='spinner-goo-blob spinner-goo-blob--r' />
      </div>
      <span className='sr-only'>{_('Loading...')}</span>
      <style>{spinnerGooCss}</style>
    </div>
  );
};

export default Spinner;

const spinnerGooCss = `
/* Uiverse csemszepp/ugly-crab-22 融合球（等比缩小版） */
.spinner-goo-stage {
  position: relative;
  width: 130px;
  height: 130px;
  border-radius: 50%;
  background: var(--color-base-200, #f4f4f5);
  filter: blur(7px) contrast(16);
}
.spinner-goo-blob {
  position: absolute;
  top: 50%;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  transform: translate(-50%, -50%);
}
.spinner-goo-blob--l {
  left: 20%;
  background: #1f2937;
  animation: spinner-osc-l 2.5s ease infinite;
}
.spinner-goo-blob--r {
  left: 80%;
  background: #3b82f6;
  animation: spinner-osc-r 2.5s ease infinite;
}
/* 暗色主题：反色（白 + 青），与原版一致 */
[data-theme$='-dark'] .spinner-goo-stage {
  background: var(--color-base-200, #18181b);
}
[data-theme$='-dark'] .spinner-goo-blob--l {
  background: #ffffff;
}
[data-theme$='-dark'] .spinner-goo-blob--r {
  background: #22d3ee;
}
@keyframes spinner-osc-l {
  0% { left: 20%; }
  50% { left: 50%; }
  100% { left: 20%; }
}
@keyframes spinner-osc-r {
  0% { left: 80%; }
  50% { left: 50%; }
  100% { left: 80%; }
}
@media (prefers-reduced-motion: reduce) {
  .spinner-goo-blob--l,
  .spinner-goo-blob--r {
    animation: none;
  }
}
`;
